#include "anyapi_item_catalog.h"
#include "item_catalog_preview.h"
#include <cassert>
#include <iostream>
int wmain(int argc,wchar_t** argv){assert(argc==2);auto entries=itemcatalog::load(argv[1]);assert(entries.size()==970);size_t triangles=0;for(auto& entry:entries){std::vector<uint8_t> pixels;try{pixels=itemcatalog::preview(argv[1],entry);}catch(const std::exception& e){std::cerr<<entry.metadata.id<<": "<<e.what()<<std::endl;return 1;}auto paths=itemcatalog::mesh_paths(entry);auto source=itemcatalog::read(std::filesystem::path(argv[1])/L"rom"/paths.front());std::vector<uint8_t> bytes(source.begin(),source.end());auto mesh=itempreview::parse(bytes);triangles+=mesh.indices.size()/3;size_t visible=0;for(size_t i=3;i<pixels.size();i+=4)visible+=pixels[i]!=0;assert(visible>10);auto corrupt=bytes;corrupt[0]=0;bool rejected=false;try{itempreview::parse(corrupt);}catch(...){rejected=true;}assert(rejected);bytes.resize(bytes.size()/2);rejected=false;try{itempreview::parse(bytes);}catch(...){rejected=true;}assert(rejected);}std::cout<<"PASS: all 970 installed item/component previews parsed/rendered; "<<triangles<<" authored triangles; invalid/truncated meshes rejected\n";}
